<script setup>
import { computed, ref, shallowRef } from 'vue'
import { parseSTL, mergeParsed, writeAsciiSTL, writeBinarySTL } from './stlio.js'
import { downloadFile } from '../shared/download.js'

const files = shallowRef([])
const summary = shallowRef([])
const loading = ref(false)
const exporting = ref(false)
const error = ref('')
const result = ref('')
const format = ref('ascii')
const prefix = ref(false)
const outputName = ref('combined.stl')
const busy = computed(() => loading.value || exporting.value)
const summaryColumns = [
  { key: 'name', label: 'File' },
  { key: 'format', label: 'Format' },
  { key: 'solids', label: 'Solids' },
  { key: 'facets', label: 'Facets' },
]
const formats = [
  { title: 'ASCII STL', value: 'ascii' },
  { title: 'Binary STL', value: 'binary' },
]
function clearResult() {
  result.value = ''
  error.value = ''
}

async function loadFiles(selected) {
  clearResult()
  files.value = []
  summary.value = []
  const list = Array.isArray(selected) ? selected : selected ? [selected] : []
  if (!list.length) return
  loading.value = true
  try {
    const parsed = await Promise.all(
      list.map(async (file) => {
        try {
          return { name: file.name, parsed: parseSTL(await file.arrayBuffer(), file.name.replace(/\.[^.]+$/, '')) }
        } catch (error) {
          return { name: file.name, error: error.message }
        }
      }),
    )
    summary.value = parsed
    files.value = parsed.filter((file) => !file.error)
  } catch (failure) {
    error.value = failure.message
  } finally {
    loading.value = false
  }
}

async function exportStl() {
  if (!files.value.length || busy.value) return
  clearResult()
  exporting.value = true
  await new Promise((resolve) => setTimeout(resolve, 0))
  try {
    const solids = mergeParsed(files.value, { prefixWithFile: prefix.value })
    const content = format.value === 'binary' ? writeBinarySTL(solids, 'CityFFD merged STL') : writeAsciiSTL(solids)
    const filename = (outputName.value.trim() || 'combined').replace(/\.stl$/i, '') + '.stl'
    downloadFile(content, filename, 'model/stl')
    result.value = `${files.value.length} files merged; ${solids.length} solids, ${solids.reduce((sum, solid) => sum + solid.count, 0)} facets. Downloaded: ${filename}.`
  } catch (failure) {
    error.value = `Could not merge STL: ${failure.message}`
  } finally {
    exporting.value = false
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: Form nhận nhiều STL, bảng chuẩn Vuestic báo trạng thái từng file, các lựa chọn phía dưới điều khiển định dạng và tên file gộp. -->
  <section>
    <h1 class="page-title">Merge STL</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportStl" @input="clearResult">
          <VaFileUpload
            id="stl-merge-files"
            v-model="fileUpload"
            type="list"
            upload-button-text="STL files"
            file-types=".stl,model/stl"
            :disabled="busy"
            @update:modelValue="loadFiles"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <!-- Bảng hiển thị dùng VaDataTable của template; các giá trị đã đọc/định dạng được giữ nguyên. -->
          <VaDataTable
            v-if="summary.length"
            :items="summary"
            :columns="summaryColumns"
            data-testid="stl-merge-summary"
            aria-label="STL files"
          >
            <template #cell(format)="{ rowData }">{{ rowData.parsed?.format }}</template>
            <template #cell(solids)="{ rowData }">{{ rowData.parsed?.solids.length }}</template>
            <template #cell(facets)="{ rowData }">{{ rowData.error || rowData.parsed?.triangleCount }}</template>
          </VaDataTable>
          <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
          <VaAlert v-if="summary.length > files.length" color="warning" role="status"
            >{{ summary.length - files.length }} files failed and will be skipped.</VaAlert
          >
          <VaSelect
            id="stl-merge-format"
            v-model="format"
            text-by="title"
            value-by="value"
            label="Output format"
            aria-label="Output format"
            :options="formats"
            :disabled="busy"
            @update:modelValue="clearResult"
          />
          <VaSwitch
            v-model="prefix"
            label="Prefix solid names with file name"
            :disabled="busy || format !== 'ascii'"
            @update:modelValue="clearResult"
          />
          <VaInput
            id="stl-merge-name"
            v-model="outputName"
            label="Output file name"
            input-aria-label="Output file name"
            :disabled="busy"
          />
          <VaButton type="submit" color="primary" :disabled="!files.length || busy" :loading="exporting"
            >Export STL</VaButton
          >
        </VaForm>
        <VaAlert v-if="error" color="danger" class="mt-4" role="alert" data-testid="tool-error">{{ error }}</VaAlert>
        <VaAlert v-if="result" color="success" class="mt-4" role="status" data-testid="tool-result">{{
          result
        }}</VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
